/// Output artifacts generated by `trf_codegen_bin`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GeneratedArtifacts {
    pub mock_control_fidl: String,
    pub injectable_universe_rs: String,
    pub injectable_universe_cml: String,
    pub realm_factory_rs: String,
    pub realm_factory_cml: String,
    pub test_root_cml: String,
    pub test_driver_cml: String,
    pub realm_builder_rs: String, // Outputs realm_builder_generated.rs
}

/// Converts an identifier string (such as `snake_case` method name) to `UpperCamelCase`.
fn to_upper_camel_case(identifier: &str) -> String {
    identifier
        .split('_')
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut characters = part.chars();
            match characters.next() {
                None => String::new(),
                Some(first_char) => {
                    first_char.to_uppercase().collect::<String>() + characters.as_str()
                }
            }
        })
        .collect()
}

/// Converts an identifier string (such as `UpperCamelCase`) to `snake_case`.
fn to_snake_case(identifier: &str) -> String {
    let mut out = String::new();
    for (i, c) in identifier.chars().enumerate() {
        if c.is_uppercase() {
            if i > 0 {
                out.push('_');
            }
            out.extend(c.to_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

/// Derives the FIDL protocol name used for Mock Control interfaces based on the mock struct name.
fn control_protocol_name(struct_name: &str, target_name: Option<&str>) -> String {
    let suffix = target_name.unwrap_or("test").replace("_", "").replace("-", "");
    format!("fuchsia.trf.mockcontrol.{}.{}Control", suffix, struct_name)
}

/// Maps known Rust primitives to their respective FIDL wire types.
/// Defaults to `string:MAX` for unrecognized types.
fn rust_type_to_fidl(rust: &str) -> Result<&'static str> {
    match rust {
        "String" | "&str" | "&String" => Ok("string:MAX"),
        "u8" => Ok("uint8"),
        "u16" => Ok("uint16"),
        "u32" => Ok("uint32"),
        "u64" => Ok("uint64"),
        "i8" => Ok("int8"),
        "i16" => Ok("int16"),
        "i32" => Ok("int32"),
        "i64" => Ok("int64"),
        "bool" => Ok("bool"),
        _ => anyhow::bail!("Unsupported Rust type for FIDL mock control: {}", rust),
    }
}

/// Derives the underlying Rust crate name for a given FIDL protocol name.
/// e.g. `fuchsia.examples.reverser.Reverser` -> `fidl_fuchsia_examples_reverser`
fn fidl_name_to_rust_crate(fidl: &str) -> String {
    let parts: Vec<&str> = fidl.split('.').collect();
    if parts.len() <= 1 {
        format!("fidl_{}", parts.join("_"))
    } else {
        format!("fidl_{}", parts[..parts.len() - 1].join("_"))
    }
}

/// Extracts the short protocol name from a fully qualified FIDL protocol path.
/// e.g. `fuchsia.examples.reverser.Reverser` -> `Reverser`
fn fidl_name_to_protocol(fidl: &str) -> String {
    fidl.split('.').next_back().unwrap().to_string()
}

/// Emits FIDL library `fuchsia.trf.mockcontrol` containing control protocols
/// for all mock declarations that specify a control implementation (`has_control_impl == true`).
fn generate_mock_control_fidl(ast: &ParsedAstResult, target_name: Option<&str>) -> Result<String> {
    let suffix = target_name.unwrap_or("test").replace("_", "").replace("-", "");
    let template = format!(
        "// Copyright 2026 The Fuchsia Authors.
// Use of this source code is governed by a BSD-style license that can be
// found in the LICENSE file.
library fuchsia.trf.mockcontrol.{};

",
        suffix
    ) + r##"{{#each mocks}}
@discoverable
closed protocol {{struct_name}}Control {
    {{#each control_methods}}
    strict {{upper_camel}}{{#if args}}(struct {
        {{#each args}}
        {{name}} {{fidl_type}};
        {{/each}}
    }){{else}}(){{/if}} -> ();
    {{/each}}
};

{{/each}}
"##;

    let mut data = serde_json::json!({ "mocks": [] });
    for mock_declaration in &ast.mock_declarations {
        if mock_declaration.has_control_impl {
            let mut methods = Vec::new();
            for method in &mock_declaration.control_methods {
                let mut args = Vec::new();
                for arg in &method.args {
                    args.push(serde_json::json!({
                        "name": arg.name.clone(),
                        "fidl_type": rust_type_to_fidl(&arg.rust_type)?
                    }));
                }
                methods.push(serde_json::json!({
                    "name": method.name.clone(),
                    "upper_camel": to_upper_camel_case(&method.name),
                    "args": args
                }));
            }
            data["mocks"].as_array_mut().unwrap().push(serde_json::json!({
                "struct_name": mock_declaration.struct_name.clone(),
                "control_methods": methods
            }));
        }
    }

    let mut reg = Handlebars::new();
    reg.register_template_string("mock_control", template)?;
    Ok(reg.render("mock_control", &data)?)
}

/// Emits CML manifest JSON for the Injectable Universe component,
/// declaring and exposing all mock protocols and mock control protocols
/// and accepting a `hat` configuration parameter.
fn generate_iu_cml(
    ast: &ParsedAstResult,
    iu_bin_name: &str,
    target_name: Option<&str>,
) -> Result<String> {
    let template = r##"{
    include: [
        "syslog/client.shard.cml"
    ],
    program: {
        runner: "elf",
        binary: "bin/{{iu_bin_name}}"
    },
    config: {
        hat: {
            type: "string",
            mutability: [ "parent" ],
            max_size: 64
        }
    },
    capabilities: [
        {{#each protocols}}
        { protocol: "{{this}}" },
        {{/each}}
    ],
    expose: [
        {{#each protocols}}
        { protocol: "{{this}}", from: "self" },
        {{/each}}
    ]
}"##;

    let mut protocols = Vec::new();
    for mock_declaration in &ast.mock_declarations {
        if !protocols.contains(&mock_declaration.protocol) {
            protocols.push(mock_declaration.protocol.clone());
        }
        if mock_declaration.has_control_impl {
            let control_protocol =
                control_protocol_name(&mock_declaration.struct_name, target_name);
            if !protocols.contains(&control_protocol) {
                protocols.push(control_protocol);
            }
        }
    }

    let mut reg = Handlebars::new();
    reg.register_template_string("iu_cml", template)?;
    let data = serde_json::json!({ "iu_bin_name": iu_bin_name, "protocols": protocols });
    Ok(reg.render("iu_cml", &data)?)
}

/// Emits Rust source code for the `injectable_universe` component main entry point,
/// reading the `hat` startup config to selectively dispatch mock protocol servers
/// and control proxies.
fn generate_iu_component_source(
    ast: &ParsedAstResult,
    mock_paths: &[String],
    target_name: Option<&str>,
) -> Result<String> {
    let suffix = target_name.unwrap_or("test").replace("_", "").replace("-", "");
    let template = format!(
        "// Auto-generated Injectable Universe component for TRF test harness.

#![allow(
    non_camel_case_types,
    unused_crate_dependencies,
    unused_imports,
    unreachable_code,
    non_snake_case,
    unreachable_patterns
)]

{{{{#each mock_stems}}}}
pub mod {{{{this}}}};
{{{{/each}}}}

use anyhow::Error;
use fuchsia_component::server::ServiceFs;
use futures::StreamExt;
use fidl_fuchsia_trf_mockcontrol_{} as trf_mc;
",
        suffix
    ) + r##"

{{#each mock_stems}}
use crate::{{this}}::*;
{{/each}}

#[fuchsia::main]
async fn main() -> Result<(), Error> {
    let config = injectable_universe_config::Config::take_from_startup_handle();
    match config.hat.as_str() {
{{#each mocks}}
        "{{struct_name}}" => run_{{struct_name}}().await?,
{{/each}}
        unknown_hat => tracing::error!(hat = %unknown_hat, "Unknown hat config"),
    }
    Ok(())
}

{{#each mocks}}
async fn run_{{struct_name}}() -> Result<(), Error> {
    let mock = std::sync::Arc::new({{struct_name}}::new());
    enum IncomingService {
        MockProto({{fidl_crate}}::{{proto}}RequestStream),
        {{#if has_control}}
        ControlProto(trf_mc::{{struct_name}}ControlRequestStream),
        {{/if}}
    }

    let mut service_fs = ServiceFs::new();
    service_fs.dir("svc").add_fidl_service(IncomingService::MockProto);
    {{#if has_control}}
    service_fs.dir("svc").add_fidl_service(IncomingService::ControlProto);
    {{/if}}
    service_fs.take_and_serve_directory_handle()?;

    service_fs.for_each_concurrent(None, |request| async {
        match request {
            IncomingService::MockProto(stream) => {
                let mock_clone = std::sync::Arc::clone(&mock);
                if let Err(e) = mock_clone.serve_{{snake_proto}}(stream).await {
                    tracing::error!("Mock server error: {:?}", e);
                }
            }
            {{#if has_control}}
            IncomingService::ControlProto(mut stream) => {
                let mock_clone = std::sync::Arc::clone(&mock);
                while let Some(Ok(req)) = stream.next().await {
                    match req {
                        {{#each control_methods}}
                        trf_mc::{{../struct_name}}ControlRequest
                            ::{{upper_camel}} {
                            {{#each args}}{{name}}, {{/each}} responder
                        } => {
                            mock_clone.{{name}}(
                                {{#each args}}{{name}}{{#unless @last}}, {{/unless}}{{/each}}
                            );
                            let _ = responder.send();
                        }
                        {{/each}}
                    }
                }
            }
            {{/if}}
        }
    }).await;
    Ok(())
}
{{/each}}
"##;

    let mock_stems: Vec<String> = mock_paths
        .iter()
        .enumerate()
        .filter_map(|(i, p)| {
            std::path::Path::new(p)
                .file_stem()
                .and_then(|s| s.to_str())
                .map(|stem| format!("mock_{i}_{stem}"))
        })
        .collect();

    let mut mocks = Vec::new();
    for mock in &ast.mock_declarations {
        let proto = fidl_name_to_protocol(&mock.protocol);
        let fidl_crate = fidl_name_to_rust_crate(&mock.protocol);
        let snake_proto = to_snake_case(&proto);

        let mut control_methods = Vec::new();
        for method in &mock.control_methods {
            control_methods.push(serde_json::json!({
                "name": method.name,
                "upper_camel": to_upper_camel_case(&method.name),
                "args": method.args,
            }));
        }

        mocks.push(serde_json::json!({
            "struct_name": mock.struct_name,
            "fidl_crate": fidl_crate,
            "proto": proto,
            "snake_proto": snake_proto,
            "has_control": mock.has_control_impl,
            "control_methods": control_methods,
        }));
    }

    let mut reg = Handlebars::new();
    reg.register_template_string("iu_rs", template)?;
    let data = serde_json::json!({
        "mock_stems": mock_stems,
        "mocks": mocks,
    });

    Ok(reg.render("iu_rs", &data)?)
}

/// Emits Rust source code for the generated `realm_builder_generated.rs` used by TD
fn generate_realm_builder_rs(ast: &ParsedAstResult, target_name: Option<&str>) -> Result<String> {
    let suffix = target_name.unwrap_or("test").replace("_", "").replace("-", "");
    let template = format!(
        "// Auto-generated RealmBuilder wrapper for TD\n\n#![allow(unused_imports, unused_crate_dependencies, non_camel_case_types, non_snake_case)]\nuse anyhow::Result;\nuse fidl_fuchsia_trf_factory::{{ConfigOverride, ConfigValue}};\nuse fidl_fuchsia_trf_mockcontrol_{} as trf_mc;\npub use trf_codegen_runtime::LifecycleEvent;\n\n",
        suffix
    ) + r##"

{{#each tests}}
pub struct TestRealm_{{fn_name}} {
    pub inner: trf_codegen_runtime::TestRealm,
}

impl std::ops::Deref for TestRealm_{{fn_name}} {
    type Target = trf_codegen_runtime::TestRealm;
    fn deref(&self) -> &Self::Target {
        &self.inner
    }
}

impl TestRealm_{{fn_name}} {
    {{#each mocks}}
    {{#each control_methods}}
    pub async fn {{name}}(
        &self{{#each args}}, {{name}}: {{rust_type}}{{/each}}
    ) -> Result<(), anyhow::Error> {
        let proxy = self.inner
            .connect_to_protocol::<trf_mc::{{../struct_name}}ControlMarker>()
            .await?;
        proxy.{{name}}(
            {{#each args}}{{name}}{{#if needs_as_str}}.as_str(){{/if}}{{#unless @last}}, {{/unless}}{{/each}}
        )
            .await
            .map_err(Into::into)
    }
    {{/each}}
    {{/each}}
}

pub async fn build_realm_for_{{fn_name}}() -> Result<TestRealm_{{fn_name}}> {
    let mut overrides = Vec::new();
    {{#each configs}}
    overrides.push(ConfigOverride {
        key: Some("{{key}}".into()),
        value: Some({{value_str}}),
        ..Default::default()
    });
    {{/each}}
    let realm = trf_codegen_runtime::TestRealm::create(overrides).await?;
    Ok(TestRealm_{{fn_name}} { inner: realm })
}
{{/each}}
"##;

    let mut tests = Vec::new();
    for test_fn in &ast.test_functions {
        let mut test_mocks = Vec::new();
        for mock_name in &test_fn.selected_mocks {
            if let Some(mock) = ast.mock_declarations.iter().find(|m| &m.struct_name == mock_name) {
                if mock.has_control_impl {
                    let mut control_methods = Vec::new();
                    for method in &mock.control_methods {
                        let mut args = Vec::new();
                        for arg in &method.args {
                            args.push(serde_json::json!({
                                "name": arg.name,
                                "rust_type": arg.rust_type,
                                "needs_as_str": arg.rust_type == "String"
                                    || arg.rust_type == "&String",
                            }));
                        }
                        control_methods.push(serde_json::json!({
                            "name": method.name,
                            "args": args,
                        }));
                    }
                    test_mocks.push(serde_json::json!({
                        "struct_name": mock.struct_name,
                        "control_methods": control_methods,
                    }));
                }
            }
        }

        let mut configs = Vec::new();
        for cfg in &test_fn.config_overrides {
            let value_str = match &cfg.value {
                crate::parser::ConfigValue::Boolean(b) => format!("ConfigValue::BoolValue({b})"),
                crate::parser::ConfigValue::Integer(i) => format!("ConfigValue::Int64Value({i})"),
                crate::parser::ConfigValue::String(s) => {
                    format!("ConfigValue::StringValue(\"{s}\".into())")
                }
                crate::parser::ConfigValue::Vector(_) => {
                    anyhow::bail!("Nested vectors in configs are not supported")
                }
            };
            configs.push(serde_json::json!({
                "key": cfg.key,
                "value_str": value_str,
            }));
        }

        tests.push(serde_json::json!({
            "fn_name": test_fn.function_name,
            "mocks": test_mocks,
            "configs": configs,
        }));
    }

    let mut reg = Handlebars::new();
    reg.register_template_string("rb_rs", template)?;
    let data = serde_json::json!({ "tests": tests });
    Ok(reg.render("rb_rs", &data)?)
}

/// Derives the FIDL marker protocol string from a rust marker.
/// Note: FIDL library names can contain underscores (e.g. `fuchsia.hardware_usb`).
/// In Rust, this maps to `fidl_fuchsia_hardware_usb`, which this function
/// will incorrectly map back to `fuchsia.hardware.usb` because it aggressively replaces
/// all underscores with dots. There is no easy workaround to unambiguously recover the
/// original library name without broader metadata context.
fn rust_marker_to_fidl_string(rust_marker: &str) -> String {
    let parts: Vec<&str> = rust_marker.split("::").collect();
    if parts.len() == 2 {
        let pkg = parts[0];
        let marker = parts[1];
        if let Some(pkg_suffix) = pkg.strip_prefix("fidl_") {
            let mut fidl_name = pkg_suffix.replace("_", ".");
            fidl_name.push('.');
            if let Some(protocol) = marker.strip_suffix("Marker") {
                fidl_name.push_str(protocol);
                return fidl_name;
            }
        }
    }
    rust_marker.to_string()
}

/// Emits Rust source code for the `realm_factory` component
fn generate_realm_factory_rs(
    ast: &ParsedAstResult,
    auto_routes: &AutoRoutes,
    cut_name: &str,
    target_name: Option<&str>,
) -> Result<String> {
    let iu_prefix =
        if let Some(pkg_name) = target_name { format!("{pkg_name}_") } else { "".to_string() };
    let iu_url = format!("{iu_prefix}injectable_universe#meta/injectable_universe.cm");
    let template = r##"// Auto-generated RealmFactory component

#![allow(unused_imports, unused_crate_dependencies, non_camel_case_types, non_snake_case)]
use anyhow::Result;
use fuchsia_component_test::{RealmBuilder, RealmInstance, ChildOptions, Route, Capability, Ref};
use fidl_fuchsia_component_decl as fdecl;
use cm_rust::{ConfigValue, ConfigSingleValue};
use fuchsia_component::server::ServiceFs;
use futures::StreamExt;
use fidl_fuchsia_trf_factory::{FactoryRequest, FactoryRequestStream};
use futures::channel::mpsc;
use fuchsia_async as fasync;

async fn create_realm(
    overrides: Vec<fidl_fuchsia_trf_factory::ConfigOverride>
) -> Result<RealmInstance> {
    let builder = RealmBuilder::new().await?;
    let mut cut_options = ChildOptions::new();
    let mut cut_overrides = Vec::new();
    for cfg in overrides {
        let value = match cfg.value {
            Some(fidl_fuchsia_trf_factory::ConfigValue::BoolValue(b)) => {
                fdecl::ConfigValue::Single(fdecl::ConfigSingleValue::Bool(b))
            }
            Some(fidl_fuchsia_trf_factory::ConfigValue::Int64Value(i)) => {
                fdecl::ConfigValue::Single(fdecl::ConfigSingleValue::Int64(i))
            }
            Some(fidl_fuchsia_trf_factory::ConfigValue::StringValue(s)) => {
                fdecl::ConfigValue::Single(fdecl::ConfigSingleValue::String(s))
            }
            None => anyhow::bail!("ConfigValue must not be None"),
            _ => anyhow::bail!("Unknown ConfigValue type"),
        };
        cut_overrides.push(fdecl::ConfigOverride {
            key: Some(cfg.key.unwrap()),
            value: Some(value),
            ..Default::default()
        });
    }
    if !cut_overrides.is_empty() {
        cut_options = cut_options.config_overrides(cut_overrides);
    }
    builder.add_child("{{cut_name}}", "{{cut_name}}#meta/{{cut_name}}.cm", cut_options).await?;

    {{#each mocks}}
    let mock_child_name_{{struct_name}} = format!("mock_{{struct_name}}");
    builder.add_child(
        &mock_child_name_{{struct_name}},
        "IU_URL_TEMPLATE",
        ChildOptions::new().config_overrides(vec![
        fdecl::ConfigOverride {
            key: Some("hat".to_string()),
            value: Some(fdecl::ConfigValue::Single(fdecl::ConfigSingleValue::String(
                "{{struct_name}}".to_string(),
            ))),
            ..Default::default()
        }
    ])).await?;
    {{/each}}

    // Add mock routes from generic parent to CUT
    {{#each mock_routes}}
    builder
        .add_route(
            Route::new()
                .capability(Capability::protocol_by_name("fuchsia.logger.LogSink"))
                .from(Ref::parent())
                .to(Ref::child(&mock_child_name_{{struct_name}})),
        )
        .await?;
    builder
        .add_route(
            Route::new()
                .capability(Capability::protocol_by_name("{{cap_str}}"))
                .from(Ref::child(&mock_child_name_{{struct_name}}))
                .to(Ref::child("{{../cut_name}}")),
        )
        .await?;
    {{#if has_control}}
    builder
        .add_route(
            Route::new()
                .capability(Capability::protocol_by_name("{{control_proto}}"))
                .from(Ref::child(&mock_child_name_{{struct_name}}))
                .to(Ref::parent()),
        )
        .await?;
    {{/if}}
    {{/each}}

    // Expose CUT protocols to RealmProxy
    {{#each auto_routes}}
    builder
        .add_route(
            Route::new()
                .capability(Capability::protocol_by_name("{{cap_str}}"))
                .from(Ref::child("{{../cut_name}}"))
                .to(Ref::parent()),
        )
        .await?;
    {{/each}}

    builder
        .add_route(
            Route::new()
                .capability(Capability::protocol_by_name("fuchsia.logger.LogSink"))
                .from(Ref::parent())
                .to(Ref::child("{{cut_name}}")),
        )
        .await?;
    builder
        .add_route(
            fuchsia_component_test::Route::new()
                .capability(fuchsia_component_test::Capability::protocol_by_name(
                    "fuchsia.sys2.LifecycleController",
                ))
                .from(fuchsia_component_test::Ref::framework())
                .to(fuchsia_component_test::Ref::parent()),
        )
        .await?;
    builder
        .add_route(
            fuchsia_component_test::Route::new()
                .capability(fuchsia_component_test::Capability::protocol_by_name(
                    "fuchsia.sys2.RealmQuery",
                ))
                .from(fuchsia_component_test::Ref::framework())
                .to(fuchsia_component_test::Ref::parent()),
        )
        .await?;

    let instance = builder.build().await?;
    Ok(instance)
}

#[fuchsia::main]
async fn main() -> Result<()> {
    use futures::StreamExt;
    let (tx, rx) = futures::channel::mpsc::unbounded();
    let task_loop = async move {
        rx.for_each_concurrent(None, |(instance, proxy_stream)| async move {
            let _ = realm_proxy::service::serve(instance, proxy_stream).await;
        }).await;
    };

    let mut fs = ServiceFs::new();
    fs.dir("svc").add_fidl_service(|stream: FactoryRequestStream| stream);
    fs.take_and_serve_directory_handle()?;

    let fs_loop = fs.for_each_concurrent(None, |stream| {
        let tx = tx.clone();
        async move {
            let mut stream = stream;
            while let Some(Ok(request)) = stream.next().await {
                match request {
                    FactoryRequest::CreateRealm { payload, responder } => {
                        let overrides = payload.overrides.unwrap_or_default();
                        match create_realm(overrides).await {
                            Ok(instance) => {
                                let (client_end, server_end) = fidl::endpoints::create_endpoints::<
                                    fidl_fuchsia_testing_harness::RealmProxy_Marker
                                >();
                                let _ = tx.unbounded_send((instance, server_end.into_stream()));
                                let _ = responder.send(Ok(client_end));
                            }
                            Err(e) => {
                                tracing::error!("Failed to create realm: {:?}", e);
                                let _ = responder.send(Err(
                                    fidl_fuchsia_testing_harness::OperationError::Invalid
                                ));
                            }
                        }
                    }
                    FactoryRequest::_UnknownMethod { .. } => tracing::warn!("Unsupported request"),
                }
            }
        }
    });

    futures::join!(fs_loop, task_loop);
    Ok(())
}
"##;

    let mut mocks = Vec::new();
    let mut mock_routes = Vec::new();
    let mut added_mock_routes = Vec::new();
    let mut added_control_protos = Vec::new(); // In case of duplicate mocks

    for mock in &ast.mock_declarations {
        mocks.push(serde_json::json!({
            "struct_name": mock.struct_name,
        }));

        let cap_str = rust_marker_to_fidl_string(&mock.protocol);
        let control_proto = control_protocol_name(&mock.struct_name, target_name);

        if !added_mock_routes.contains(&cap_str) {
            added_mock_routes.push(cap_str.clone());

            let mut add_control = false;
            if mock.has_control_impl && !added_control_protos.contains(&control_proto) {
                added_control_protos.push(control_proto.clone());
                add_control = true;
            }

            mock_routes.push(serde_json::json!({
                "struct_name": mock.struct_name,
                "cap_str": cap_str,
                "has_control": add_control,
                "control_proto": control_proto,
            }));
        }
    }

    let mut auto_routes_extracted = Vec::new();
    for route in &auto_routes.routes {
        if route.source == "CUT" && route.target == "TD" {
            let cap_str = rust_marker_to_fidl_string(&route.protocol);
            auto_routes_extracted.push(serde_json::json!({
                "cap_str": cap_str,
            }));
        }
    }

    let template = template.replace("IU_URL_TEMPLATE", &iu_url);
    let mut reg = Handlebars::new();
    reg.register_template_string("rf_rs", &template)?;
    let data = serde_json::json!({
        "cut_name": cut_name,
        "mocks": mocks,
        "mock_routes": mock_routes,
        "auto_routes": auto_routes_extracted,
    });

    Ok(reg.render("rf_rs", &data)?)
}

/// Emits CML manifest JSON for the Test Driver component.
/// We use a hardcoded list of protocols (like `fuchsia.trf.factory.Factory`) rather than inspecting
/// the `_ast` parameter, because all dynamic CUT exposed protocols are multiplexed via the
/// RealmFactory rather than being statically routed to the Test Driver component manifest directly.
fn generate_test_driver_cml(td_bin_name: &str, _ast: &ParsedAstResult) -> String {
    // We currently hardcode fuchsia.trf.factory.Factory as the only required protocol.
    // In the future, the AST might declare other protocols needed by the test driver.
    let protocols = ["fuchsia.trf.factory.Factory".to_string()];
    let use_blocks: Vec<String> =
        protocols.iter().map(|p| format!("{{ protocol: \"{p}\" }}")).collect();
    let use_json = use_blocks.join(
        ",
        ",
    );

    let template = format!(
        r##"{{
    include: [
        "//src/sys/test_runners/rust/default.shard.cml",
        "syslog/client.shard.cml"
    ],
    program: {{
        binary: "bin/{0}"
    }},
    use: [
        {1}
    ],
    expose: [
        {{
            protocol: "fuchsia.test.Suite",
            from: "self"
        }}
    ]
}}"##,
        td_bin_name, use_json
    );
    template
}

/// Emits the capability routing setup for the Realm Factory component manifest
fn generate_realm_factory_cml(rf_bin_name: &str, _ast: &ParsedAstResult) -> String {
    let template = format!(
        r##"{{
    include: [
        "syslog/client.shard.cml",
        "//sdk/lib/sys/component/realm_builder.shard.cml"
    ],
    program: {{
        runner: "elf",
        binary: "bin/{rf_bin_name}"
    }},
    capabilities: [
        {{ protocol: "fuchsia.trf.factory.Factory" }}
    ],
    use: [
        {{ protocol: "fuchsia.component.Realm", from: "framework" }}
    ],
    expose: [
        {{ protocol: "fuchsia.trf.factory.Factory", from: "self" }}
    ]
}}"##
    );
    template
}

/// Synthesizes the test root component interconnecting the Test Driver and Realm Factory.
fn generate_test_root_cml(_ast: &ParsedAstResult, target_name: Option<&str>) -> String {
    let pkg_name = target_name
        .map(|t| format!("{}_realm_factory", t))
        .unwrap_or_else(|| "realm-factory".into());
    let template = r##"{
    include: [
        "syslog/client.shard.cml"
    ],
    children: [
        { name: "test_driver", url: "#meta/test_driver.cm" },
        { name: "realm_factory", url: "REALM_FACTORY_PKG_NAME#meta/realm_factory.cm" },
    ],"##
        .replace("REALM_FACTORY_PKG_NAME", &pkg_name);
    let template = template
        + r##"
    offer: [
        {
            protocol: [
                "fuchsia.logger.LogSink",
                "fuchsia.process.Launcher"
            ],
            from: "parent",
            to: [ "#test_driver", "#realm_factory" ]
        },
        {
            dictionary: "diagnostics",
            from: "parent",
            to: [ "#test_driver", "#realm_factory" ]
        },
        {
            storage: [ "data", "cache", "tmp" ],
            from: "parent",
            to: [ "#test_driver", "#realm_factory" ]
        },
        {
            protocol: "fuchsia.trf.factory.Factory",
            from: "#realm_factory",
            to: "#test_driver"
        }
    ],
    expose: [
        {
            protocol: "fuchsia.test.Suite",
            from: "#test_driver"
        }
    ]
}"##;
    template
}

/// Main entry point for artifact generation. Accepts parsed Rust test AST and inferred
/// capability routes
/// and produces all code and manifest artifacts required for the TRF test harness.
pub fn generate_artifacts(
    ast: &ParsedAstResult,
    auto_routes: &AutoRoutes,
    target_name: Option<&str>,
    cut_component_name: Option<&str>,
    mock_paths: &[String],
) -> Result<GeneratedArtifacts> {
    let iu_bin_name = target_name
        .map(|t| format!("{t}_iu_bin"))
        .unwrap_or_else(|| "injectable_universe".to_string());
    let td_bin_name =
        target_name.map(|t| format!("{t}_td_bin")).unwrap_or_else(|| "test_driver".to_string());
    let cut_name = cut_component_name.unwrap_or("cut");
    let rf_bin_name =
        target_name.map(|t| format!("{t}_rf_bin")).unwrap_or_else(|| "realm_factory".to_string());

    let mock_control_fidl = generate_mock_control_fidl(ast, target_name)?;
    let injectable_universe_rs = generate_iu_component_source(ast, mock_paths, target_name)?;
    let injectable_universe_cml = generate_iu_cml(ast, &iu_bin_name, target_name)?;
    let test_driver_cml = generate_test_driver_cml(&td_bin_name, ast);
    let realm_builder_rs = generate_realm_builder_rs(ast, target_name)?;

    let realm_factory_rs = generate_realm_factory_rs(ast, auto_routes, cut_name, target_name)?;
    let realm_factory_cml = generate_realm_factory_cml(&rf_bin_name, ast);
    let test_root_cml = generate_test_root_cml(ast, target_name.as_deref());

    Ok(GeneratedArtifacts {
        mock_control_fidl,
        injectable_universe_rs,
        injectable_universe_cml,
        test_driver_cml,
        realm_builder_rs,
        realm_factory_cml,
        realm_factory_rs,
        test_root_cml,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_to_upper_camel_case() {
        assert_eq!(to_upper_camel_case("camel_case"), "CamelCase");
        assert_eq!(to_upper_camel_case("single"), "Single");
        assert_eq!(to_upper_camel_case("_leading"), "Leading");
    }

    #[test]
    fn test_to_snake_case() {
        assert_eq!(to_snake_case("UpperCamelCase"), "upper_camel_case");
        assert_eq!(to_snake_case("MyProtocol"), "my_protocol");
        assert_eq!(to_snake_case("simple"), "simple");
    }

    #[test]
    fn test_control_protocol_name() {
        assert_eq!(
            control_protocol_name("MyMock", None),
            "fuchsia.trf.mockcontrol.test.MyMockControl"
        );
    }

    #[test]
    fn test_rust_type_to_fidl() {
        assert_eq!(rust_type_to_fidl("String").unwrap(), "string:MAX");
        assert_eq!(rust_type_to_fidl("u32").unwrap(), "uint32");
        assert_eq!(rust_type_to_fidl("bool").unwrap(), "bool");
        assert!(rust_type_to_fidl("UnknownType").is_err());
    }

    #[test]
    fn test_fidl_name_to_rust_crate() {
        assert_eq!(
            fidl_name_to_rust_crate("fuchsia.examples.reverser.Reverser"),
            "fidl_fuchsia_examples_reverser"
        );
    }

    #[test]
    fn test_fidl_name_to_protocol() {
        assert_eq!(fidl_name_to_protocol("fuchsia.examples.reverser.Reverser"), "Reverser");
    }

    #[test]
    fn test_generate_test_root_cml_not_empty() {
        let ast = ParsedAstResult::default();
        let cml = generate_test_root_cml(&ast, None);
        assert!(cml.contains("syslog/client.shard.cml"));
        assert!(cml.contains("fuchsia.test.Suite"));
    }

    #[test]
    fn test_generate_mock_control_fidl() {
        let mut ast = ParsedAstResult::default();
        ast.mock_declarations.push(crate::parser::MockDeclaration {
            struct_name: "MockReverser".to_string(),
            protocol: "fuchsia.examples.reverser.Reverser".to_string(),
            has_control_impl: true,
            control_methods: vec![],
        });

        let fidl = generate_mock_control_fidl(&ast, None).unwrap();
        assert!(fidl.contains("closed protocol MockReverserControl {"));
    }

    #[test]
    fn test_generate_iu_cml() {
        let mut ast = ParsedAstResult::default();
        ast.mock_declarations.push(crate::parser::MockDeclaration {
            struct_name: "MockReverser".to_string(),
            protocol: "fuchsia.examples.reverser.Reverser".to_string(),
            has_control_impl: true,
            control_methods: vec![],
        });

        let cml = generate_iu_cml(&ast, "my_iu_bin", None).unwrap();
        assert!(cml.contains("fuchsia.examples.reverser.Reverser"));
        assert!(cml.contains("fuchsia.trf.mockcontrol.test.MockReverserControl"));
        assert!(cml.contains("bin/my_iu_bin"));
    }

    #[test]
    fn test_generate_iu_component_source() {
        let mut ast = ParsedAstResult::default();
        ast.mock_declarations.push(crate::parser::MockDeclaration {
            struct_name: "MockReverser".to_string(),
            protocol: "fuchsia.examples.reverser.Reverser".to_string(),
            has_control_impl: false,
            control_methods: vec![],
        });

        let paths = vec!["mocks.rs".to_string()];
        let rs = generate_iu_component_source(&ast, &paths, None).unwrap();
        assert!(rs.contains("pub mod mock_0_mocks;"));
        assert!(rs.contains("\"MockReverser\" => run_MockReverser().await?"));
    }

    #[test]
    fn test_generate_realm_builder_rs() {
        let mut ast = ParsedAstResult::default();
        ast.test_functions.push(crate::parser::TestFunction {
            function_name: "test_reverse_string".to_string(),
            config_overrides: vec![],
            selected_mocks: vec!["MockReverser".to_string()],
            protocol_connections: vec![],
        });

        let rs = generate_realm_builder_rs(&ast, None).unwrap();
        assert!(rs.contains("pub struct TestRealm_test_reverse_string"));
        assert!(rs.contains(
            "pub async fn build_realm_for_test_reverse_string() -> Result<TestRealm_test_reverse_string>"
        ));
    }

    #[test]
    fn test_generate_realm_factory_rs() {
        let ast = ParsedAstResult::default();
        let auto_routes = AutoRoutes::default();
        let rs = generate_realm_factory_rs(&ast, &auto_routes, "reverser", None).unwrap();
        assert!(rs.contains(
            "builder.add_child(\"reverser\", \"reverser#meta/reverser.cm\", cut_options).await?;"
        ));
    }

    #[test]
    fn test_generate_test_driver_cml() {
        let ast = ParsedAstResult::default();
        let cml = generate_test_driver_cml("my_td_bin", &ast);
        assert!(cml.contains("bin/my_td_bin"));
    }

    #[test]
    fn test_generate_realm_factory_cml() {
        let ast = ParsedAstResult::default();
        let cml = generate_realm_factory_cml("my_rf_bin", &ast);
        assert!(cml.contains("bin/my_rf_bin"));
    }
}
